default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('AllowLocalPolicyMerge', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile [AllowLocalPolicyMerge]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

---

{{ if .Vars.win11cis_level_1 }}
  {{ if .Vars.win11cis_rule_9_3_4 }}
    {{ if not .Vars.win11cis_win_skip_for_test }}
registry:
  HKLM\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile\AllowLocalPolicyMerge:
    title: "9.3.4 | Ensure 'Windows Firewall: Public: Settings: Apply local firewall rules' is set to 'No' | AllowLocalPolicyMerge"
    exists: true
    value: 0
    type: REG_DWORD
    meta:
      workstation: 1
      CIS_ID:
        - 9.3.4
      NIST800-53R5:
        - SC-7
        - SC-7(5)
    {{ end }}
  {{ end }}
{{ end }}

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsFirewall\PublicProfile' -Name 'AllowLocalPolicyMerge' -Value 0 -PropertyType DWord -Force | Out-Null
exit 0
